test('cancel stops generation, does not dispatch tools or cancel a background task',async()=>{let entered;const started=new Promise(r=>entered=r);let calls=0;const f=await fixture({tools:[tool(async()=>{calls++;})],modelClient:{complete({signal}){entered();return new Promise((_,reject)=>signal.addEventListener('abort',()=>reject(Error('aborted'))));}}});await f.adapter.submit(f.submission);await started;assert.equal((await f.adapter.cancel(request({execution:f.execution,reason:'interrupt'}))).value.status,'requested');assert.equal((await finished(f)).status,'canceled');assert.equal(calls,0);});
test('authorized history resumes in new adapter; identity change and revoked history rejected',async()=>{const f=await fixture();await f.adapter.submit(f.submission);await finished(f);const restarted=new BuiltinInteractionRuntime(f.options);assert.equal((await restarted.resumeSession(request({session:f.session}))).ok,true);const denied=await restarted.resumeSession(request({session:f.session},{...context,trigger:{...context.trigger,requester:{...context.trigger.requester,externalUserId:'other'}}}));assert.equal(denied.ok,false);const revoked=new BuiltinInteractionRuntime({...f.options,authorize:async()=>false});assert.equal((await revoked.resumeSession(request({session:f.session}))).ok,false);});
test('stale epoch and mismatched invocation are rejected',async()=>{const f=await fixture();for(const field of ['specHash','configRevision','preparedAgentHandle']){const forged=structuredClone(f.submission);forged.payload.session[field]='forged';assert.equal((await f.adapter.submit(forged)).status,'rejected');}const bad=structuredClone(f.submission);bad.authorizationContext.invocationId='spoof';assert.equal((await f.adapter.submit(bad)).status,'rejected');await f.adapter.submit(f.submission);await finished(f);const stale=structuredClone(f.submission);stale.payload.execution.executionId='x2';assert.equal((await f.adapter.submit(stale)).status,'rejected');});
