function nextSubmission(f,n,text){const value=structuredClone(f.submission);value.payload.execution.executionId=`x${n}`;value.payload.execution.invocationId=`i${n}`;value.payload.execution.target={...value.payload.execution.target,turnId:`turn${n}`,epoch:n};value.payload.input={...value.payload.input,turnId:`turn${n}`,epoch:n,messageRefs:[ref(text)]};value.payload.idempotencyKey=`turn${n}`;value.authorizationContext={...value.authorizationContext,invocationId:`i${n}`,triggerId:`trigger${n}`,target:value.payload.execution.target};return value;}
test('successful JSONL history preserves identical turn occurrences, no SQL-store body snapshots',async()=>{const captured=[];const f=await fixture({modelClient:{async complete({messages}){captured.push(structuredClone(messages));return response({text:'PRIVATE_FINAL'});}}});await f.adapter.submit(f.submission);await finished(f);const second=nextSubmission(f,2,'hello');await f.adapter.submit(second);await finished({...f,execution:second.payload.execution});assert.equal(captured[1].filter(m=>m.role==='user'&&m.content==='hello').length,2);assert.equal(captured[1].filter(m=>m.content==='PRIVATE_FINAL').length,1);const stored=JSON.stringify([...f.sessionStore.records.values()]);assert.equal(stored.includes('PRIVATE_FINAL'),false);assert.equal(stored.includes('"content"'),false);const entries=readFileSync(join(f.options.journal.root,f.session.recordLocation.resourceId,'current.jsonl'),'utf8').trim().split('\n').map(JSON.parse);assert.equal(entries.filter(e=>e.kind==='message'&&e.value.content==='PRIVATE_FINAL').length,1);assert.equal(entries.filter(e=>e.kind==='attempt_message').length,4);});
test('terminal journal commit repairs failed metadata publication without repeating model or tools',async()=>{let modelCalls=0;const f=await fixture({modelClient:{async complete(){modelCalls++;return response();}}});const original=f.sessionStore.compareAndSetMany.bind(f.sessionStore);let published;const publication=new Promise(resolve=>published=resolve);let fail=true;f.sessionStore.compareAndSetMany=async changes=>{if(fail&&changes.some(c=>c.value.status==='succeeded')){published();throw Error('injected metadata outage');}return original(changes);};await f.adapter.submit(f.submission);await publication;await f.adapter.shutdown();assert.equal([...f.sessionStore.records.values()].some(r=>r.value.status==='succeeded'),false);fail=false;const restarted=new BuiltinInteractionRuntime(f.options);assert.equal((await restarted.getStatus(request({execution:f.execution}))).value.status,'succeeded');assert.equal((await restarted.resumeSession(request({session:f.session}))).ok,true);assert.equal((await restarted.submit(f.submission)).status,'accepted');assert.equal(modelCalls,1);});
test('committed user survives failure while invalid model tool response is never published',async()=>{let round=0;const captured=[];const f=await fixture({modelClient:{async complete({messages}){captured.push(messages);if(++round===1)return response({text:'FAILED_PRIVATE',toolCalls:[{id:'bad',name:'shell.exec',arguments:{}}]});return response({text:'good'});}}});await f.adapter.submit(f.submission);assert.equal((await finished(f)).status,'failed');const second=nextSubmission(f,2,'next');await f.adapter.submit(second);assert.equal((await finished({...f,execution:second.payload.execution})).status,'succeeded');assert.equal(captured[1].some(m=>m.content==='FAILED_PRIVATE'),false);assert.equal(captured[1].some(m=>m.content==='hello'),true);assert.equal(readFileSync(join(f.options.journal.root,f.session.recordLocation.resourceId,'current.jsonl'),'utf8').includes('FAILED_PRIVATE'),false);});
test('close releases committed history references without introducing legacy body fields',async()=>{const f=await fixture();await f.adapter.submit(f.submission);await finished(f);assert.equal((await f.adapter.closeSession(request({session:f.session,reason:'finished'}))).value.status,'closed');const session=[...f.sessionStore.records.values()].find(r=>r.value.handle?.sessionId==='c').value;assert.deepEqual(session.messageRefs,[]);assert.equal('messages' in session,false);assert.equal(session.closed,true);});

