async function reconfigured(f,{revision='2',tools=[],modelClient={async complete(){return response({text:'new reply'});}}}={}){
 const adapter=new BuiltinInteractionRuntime({...f.options,tools,modelClient}),prior=[...f.sessionStore.records.values()].find(r=>r.value.spec)?.value.spec;
 const spec={...prior,specHash:`hash-${revision}`,instructions:ref(`system-${revision}`),sourceVersions:{...prior.sourceVersions,entityConfig:revision,profile:revision},platformTools:tools.map(t=>t.name)};
 const c={...context,configRevision:revision};const p=await adapter.prepareAgent(request({runtime,spec,policy:{policyRef:'policy',allowedOptionalDegradations:[],secretDelivery:'protected_only'},idempotencyKey:spec.specHash},c));assert.equal(p.ok,true);
 const session=await adapter.createSession(request({handle:p.value,sessionId:'c',idempotencyKey:'c',contextBootstrap:{scope:{kind:'interaction',conversationId:'c'},mode:'new',snapshotId:'c',bundleRef:ref('bundle'),inputRefs:[],knowledgeScopes:[],workStateViewRef:ref('state'),budget:{maxTokens:10000,maxBytes:10000},provenance:{sourceRefs:[],authorizationDecisionRef:'auth',createdAt:new Date().toISOString()}}},c));assert.equal(session.ok,true);
 const submission=nextSubmission(f,2,'new message');submission.payload.session=session.value;submission.authorizationContext.configRevision=revision;
 return{...f,adapter,session:session.value,submission,execution:submission.payload.execution};
}
