test('queued compatible group batch joins only after all slow tool results and durable input commit',async()=>{
 let release,entered,round=0;const hold=new Promise(r=>release=r),started=new Promise(r=>entered=r),inputs=[];
 const f=await fixture({authorizeHistoryBatch:()=>true,tools:[tool(async()=>{entered();await hold;return{status:'queued',taskId:'synthetic'};})],modelClient:{async complete(input){inputs.push(JSON.parse(JSON.stringify(input.messages)));return response(++round===1?{toolCalls:[{id:'slow-call',name:'task_create',arguments:{input:'slow'}}]}:{text:'done'});}}});
 f.submission.payload.input.historyBatchId='first';await f.adapter.submit(f.submission);await started;
 const next=structuredClone(f.submission);next.operationId='second-op';next.payload.idempotencyKey='second-op';Object.assign(next.payload.execution,{executionId:'x2',invocationId:'i2',target:{...next.payload.execution.target,turnId:'t2',epoch:2}});Object.assign(next.authorizationContext,{invocationId:'i2',target:next.payload.execution.target});Object.assign(next.payload.input,{turnId:'t2',epoch:2,historyBatchId:'second',messageRefs:[ref('SECOND-BATCH-MARKER')]});await f.adapter.submit(next);
 assert.equal((await f.adapter.getInputCommit(request({execution:next.payload.execution,batchId:'second'},next.authorizationContext))).value.status,'accepted');assert.equal(round,1);release();await finished(f);
 for(let i=0;i<200;i++){const status=await f.adapter.getStatus(request({execution:next.payload.execution},next.authorizationContext));if(status.ok&&status.value.status==='succeeded')break;await new Promise(r=>setTimeout(r,2));}
 assert.equal((await f.adapter.getInputCommit(request({execution:next.payload.execution,batchId:'second'},next.authorizationContext))).value.status,'committed');assert.equal(inputs.length,2);assert.equal((JSON.stringify(inputs[1]).match(/SECOND-BATCH-MARKER/g)??[]).length,1);assert.equal(inputs[1].filter(m=>m.role==='tool').length,1);
});

async function delivery(f,execution=f.execution,c=f.submission.authorizationContext,cursor){const out=await f.adapter.readInteractionEvents(request({execution,...(cursor?{cursor}:{})},c));assert.equal(out.ok,true,JSON.stringify(out));return out.value;}
test('ordinary tool-call content is delivered before tool completion and pending input commits at the paired boundary',async()=>{let enter,release,round=0;const started=new Promise(r=>enter=r),hold=new Promise(r=>release=r),inputs=[];const f=await fixture({tools:[tool(async()=>{enter();await hold;return{taskId:'t'};})],modelClient:{async complete(value){inputs.push(structuredClone(value.messages));return response(++round===1?{text:'Starting read-only work',toolCalls:[{id:'slow',name:'task_create',arguments:{input:'work'}}]}:{text:'Finished current response'});}}});f.submission.payload.input.inputId='stable-first';await f.adapter.submit(f.submission);await started;let events=await delivery(f);assert.deepEqual(events.events.map(e=>e.type),['input_committed','output']);assert.equal(f.outputs.includes('Starting read-only work'),true);assert.equal((await f.adapter.getStatus(request({execution:f.execution}))).value.status,'running');const second=nextSubmission(f,2,'PENDING-INPUT');second.payload.input.inputId='stable-second';const accepted=await f.adapter.submit(second);assert.equal(accepted.state,'queued');assert.equal((await f.adapter.getInputCommit(request({execution:second.payload.execution,batchId:'stable-second'},second.authorizationContext))).value.status,'accepted');release();await finished(f);await finished({...f,execution:second.payload.execution,submission:second});events=await delivery(f);assert.equal(events.events.filter(e=>e.type==='output').length,2);assert.ok(inputs[1].some(m=>m.role==='assistant'&&m.content==='Starting read-only work'&&m.toolCalls?.length===1),'Actual assistant protocol content must remain in history');assert.equal(f.outputs.filter(x=>x==='Starting read-only work').length,1);assert.equal(new Set(events.events.map(e=>e.eventId)).size,events.events.length);assert.equal((JSON.stringify(inputs[1]).match(/PENDING-INPUT/g)||[]).length,1);assert.equal(inputs[1].filter(e=>e.role==='tool').length,1);assert.ok(events.events.find(e=>e.type==='output'&&e.inputIds.length===2).inputIds.includes('stable-second'));assert.equal((await delivery(f,f.execution,f.submission.authorizationContext,events.cursor)).events.length,0);});
test('ordinary content may name a tool verbatim and the system adds no tool label or status',async()=>{const text='模型自己的普通回复，包含 task_create 名称。';let round=0;const f=await fixture({modelClient:{async complete(){return response(++round===1?{text,toolCalls:[{id:'named-content',name:'task_create',arguments:{input:'work'}}]}:{text:'Final model content'});}}});await f.adapter.submit(f.submission);await finished(f);assert.deepEqual(f.outputs,[text,'Final model content']);assert.equal((await delivery(f)).events.filter(e=>e.type==='output').length,2);});
test('a silent tool round creates no invented visible message',async()=>{let round=0;const f=await fixture({modelClient:{async complete(){return response(++round===1?{toolCalls:[{id:'silent',name:'task_create',arguments:{input:'work'}}]}:{text:'Only the final answer'});}}});await f.adapter.submit(f.submission);await finished(f);assert.deepEqual(f.outputs,['Only the final answer']);const events=await delivery(f);assert.equal(events.events.filter(e=>e.type==='output').length,1);});
test('rejected staged pending commit cannot leak its text into the next model request',async()=>{let enter,release,round=0,allow=true;const started=new Promise(r=>enter=r),hold=new Promise(r=>release=r),inputs=[];const f=await fixture({authorizeHistoryBatch:id=>id!=='second'||allow,tools:[tool(async()=>{enter();await hold;return{};})],modelClient:{async complete(value){inputs.push(structuredClone(value.messages));return response(++round===1?{toolCalls:[{id:'slow',name:'task_create',arguments:{input:'work'}}]}:{text:'safe'});}}});await f.adapter.submit(f.submission);await started;const next=nextSubmission(f,2,'UNCOMMITTED-PRIVATE');next.payload.input.historyBatchId='second';await f.adapter.submit(next);allow=false;release();await finished(f);assert.equal(inputs.length,2);assert.equal(JSON.stringify(inputs).includes('UNCOMMITTED-PRIVATE'),false);assert.equal((await f.adapter.getInputCommit(request({execution:next.payload.execution,batchId:'second'},next.authorizationContext))).value.status,'unknown');});
test('accepted incompatible pending input has no invocation-lifetime expiry before it starts',async()=>{let now=1800000000000,enter,release,round=0;const hold=new Promise(r=>release=r),started=new Promise(r=>enter=r);const f=await fixture({inputQueue:new BuiltinInputQueue(),now:()=>now,modelClient:{async complete(){if(++round===1){enter();await hold;}return response({text:'done'});}}});await f.adapter.submit(f.submission);await started;const second=nextSubmission(f,2,'later');second.authorizationContext.configRevision='1';second.authorizationContext.trigger={...second.authorizationContext.trigger,requester:{...second.authorizationContext.trigger.requester,externalUserId:'other'}};const group={...f.submission.authorizationContext.conversation,kind:'group'};/* compatibility is tested by a generation change below rather than recasting identity */
 const next=await reconfigured(f,{modelClient:{async complete(){return response({text:'new snapshot'});}}});next.submission.deadlineAt=new Date(now+60).toISOString();next.submission.authorizationContext.expiresAt=new Date(now+60).toISOString();assert.equal((await next.adapter.submit(next.submission)).state,'queued');now+=100000;release();await finished(f);assert.equal((await finished(next)).status,'succeeded');});
function runtimeKey(kind,id){const canonical=v=>Array.isArray(v)?'['+v.map(canonical).join(',')+']':v&&typeof v==='object'?'{'+Object.entries(v).sort(([a],[b])=>a.localeCompare(b)).map(([k,x])=>JSON.stringify(k)+':'+canonical(x)).join(',')+'}':JSON.stringify(v);return 'builtin:'+kind+':'+createHash('sha256').update(canonical(runtime)).digest('hex')+':'+id;}
async function seedInterrupted(f,{owner=true,pending=false}={}){const dead=spawnSync(process.execPath,['-e','process.exit(0)']);assert.equal(dead.status,0);const sk=runtimeKey('session','c'),session=f.sessionStore.records.get(sk);f.sessionStore.records.set(sk,{version:session.version+1,value:{...session.value,activeExecution:'x',...(pending?{pendingExecutionKeys:[runtimeKey('execution','x2')]}:{})}});const state={request:structuredClone(f.submission),fingerprint:'seeded-legacy',status:'running',started:true,eventRefs:[],deliveryRefs:[],...(owner?{owner:{pid:dead.pid,instanceId:'exited-owner'}}:{})};f.sessionStore.records.set(runtimeKey('execution','x'),{version:1,value:state});if(pending){const r=nextSubmission(f,2,'DURABLE-PENDING');f.sessionStore.records.set(runtimeKey('execution','x2'),{version:1,value:{request:r,fingerprint:'seeded-pending',status:'queued',eventRefs:[],deliveryRefs:[]}});}return dead.pid;}
test('dead process owner is isolated without replay; a new input completes in the same session',async()=>{const seen=[];const f=await fixture({modelClient:{async complete(input){seen.push(input.messages);return response({text:'new response'});}}});await seedInterrupted(f);const next=nextSubmission(f,2,'NEW-AFTER-RESTART');const restarted=new BuiltinInteractionRuntime(f.options);assert.equal((await restarted.submit(next)).status,'accepted');assert.equal((await finished({...f,adapter:restarted,execution:next.payload.execution,submission:next})).status,'succeeded');assert.equal(seen.length,1);assert.equal(JSON.stringify(seen).includes('hello'),false);assert.equal((await restarted.getStatus(request({execution:f.execution}))).value.status,'unknown');assert.equal(f.operationStore.records.size,0);});
test('legacy owner without host proof remains gated; explicit exclusive-owner proof recovers without deleting history',async()=>{const f=await fixture();await seedInterrupted(f,{owner:false});const next=nextSubmission(f,2,'new');const conservative=new BuiltinInteractionRuntime(f.options);assert.equal((await conservative.submit(next)).status,'rejected');const recovered=new BuiltinInteractionRuntime({...f.options,previousOwnerUnavailable:()=>true});assert.equal((await recovered.submit(next)).status,'accepted');assert.equal((await finished({...f,adapter:recovered,execution:next.payload.execution,submission:next})).status,'succeeded');assert.equal((await recovered.getStatus(request({execution:f.execution}))).value.status,'unknown');});
test('durable pending references survive runtime recreation and started old work is never rerun',async()=>{const seen=[];const f=await fixture({modelClient:{async complete(value){seen.push(value.messages);return response({text:'recovered'});}}});await seedInterrupted(f,{pending:true});const next=nextSubmission(f,3,'NEW-THIRD');const recovered=new BuiltinInteractionRuntime(f.options);assert.equal((await recovered.submit(next)).status,'accepted');await finished({...f,adapter:recovered,execution:next.payload.execution,submission:next});const combined=JSON.stringify(seen);assert.match(combined,/DURABLE-PENDING/);assert.match(combined,/NEW-THIRD/);assert.equal(combined.includes('hello'),false);assert.equal((await recovered.getStatus(request({execution:f.execution}))).value.status,'unknown');});
test('large admitted input is not rejected by legacy byte quotas',async()=>{const text='L'.repeat(300000);const f=await fixture({readContent:async ref=>ref.resourceId==='large'?text:ref.resourceId});f.submission.payload.input.messageRefs=[ref('large')];await f.adapter.submit(f.submission);assert.equal((await finished(f)).status,'succeeded');});

test('accepted metadata before RAM scheduling recovers without a new input and emits one committed/output sequence',async()=>{let calls=0;const f=await fixture({modelClient:{async complete(){calls++;return response({text:'auto recovered'});}}});await seedInterrupted(f);const k=runtimeKey('execution','x'),row=f.sessionStore.records.get(k);row.value.status='accepted';row.value.started=false;const restored=new BuiltinInteractionRuntime(f.options),statuses=[];for(let i=0;i<150;i++){const s=await restored.getStatus(request({execution:f.execution}));assert.equal(s.ok,true);statuses.push(s.value.status);if(s.value.status==='succeeded')break;await new Promise(r=>setTimeout(r,2));}assert.equal(statuses.at(-1),'succeeded');assert.equal(statuses.includes('unknown'),false);assert.equal(calls,1);const events=await restored.readInteractionEvents(request({execution:f.execution}));assert.equal(events.value.events.filter(e=>e.type==='input_committed').length,1);assert.equal(events.value.events.filter(e=>e.type==='output').length,1);});
test('a live process owner cannot be cleared by a timer or a stale host recovery hint',async()=>{const f=await fixture();await seedInterrupted(f);const row=f.sessionStore.records.get(runtimeKey('execution','x'));row.value.owner={pid:process.pid,instanceId:'another-live-owner'};const restored=new BuiltinInteractionRuntime({...f.options,previousOwnerUnavailable:()=>true});const next=nextSubmission(f,2,'must wait');assert.equal((await restored.submit(next)).status,'rejected');assert.equal(f.sessionStore.records.get(runtimeKey('session','c')).value.activeExecution,'x');assert.equal(row.value.status,'running');});
test('staged input metadata failure does not enter model context or publish a false failed receipt',async()=>{let enter,release,round=0;const started=new Promise(r=>enter=r),hold=new Promise(r=>release=r),seen=[];const f=await fixture({tools:[tool(async()=>{enter();await hold;return{};})],modelClient:{async complete(value){seen.push(structuredClone(value.messages));return response(++round===1?{toolCalls:[{id:'tool',name:'task_create',arguments:{input:'work'}}]}:{text:'safe'});}}});await f.adapter.submit(f.submission);await started;const next=nextSubmission(f,2,'UNCOMMITTED-STORAGE-BODY');await f.adapter.submit(next);const original=f.sessionStore.compareAndSetMany.bind(f.sessionStore);f.sessionStore.compareAndSetMany=async changes=>{if(changes.some(c=>c.key===runtimeKey('execution','x2')&&c.value.inputCommitted))throw Error('synthetic metadata outage');return original(changes);};release();await finished(f);assert.equal(JSON.stringify(seen).includes('UNCOMMITTED-STORAGE-BODY'),false);assert.equal(f.sessionStore.records.get(runtimeKey('execution','x2')).value.status,'unknown');});

test('stable input execution rejects changed payload and parse failure never emits user-visible output',async()=>{const f=await fixture({modelClient:{async complete(){throw new SyntaxError('synthetic incomplete response');}}});await f.adapter.submit(f.submission);await finished(f);const events=await delivery(f);assert.equal(events.events.filter(e=>e.type==='output').length,0);assert.equal(events.events.filter(e=>e.type==='input_committed').length,1);const changed=structuredClone(f.submission);changed.payload.input.messageRefs=[ref('changed')];assert.equal((await f.adapter.submit(changed)).status,'rejected');assert.equal((await f.adapter.getInputCommit(request({execution:f.execution,batchId:'turn'}))).value.status,'committed');});
test('different trusted route generation never merges into the active execution at a tool boundary',async()=>{let enter,release,round=0;const start=new Promise(r=>enter=r),hold=new Promise(r=>release=r),seen=[];const f=await fixture({tools:[tool(async()=>{enter();await hold;return{};})],modelClient:{async complete(value){seen.push(structuredClone(value.messages));return response(++round===1?{toolCalls:[{id:'slow',name:'task_create',arguments:{input:'work'}}]}:{text:'done'});}}});f.submission.payload.input.routeBinding='old-bound-account';await f.adapter.submit(f.submission);await start;const next=nextSubmission(f,2,'NEW-ROUTE-BODY');next.payload.input.routeBinding='new-bound-account';await f.adapter.submit(next);release();await finished(f);await finished({...f,execution:next.payload.execution,submission:next});assert.equal(seen.length,3);assert.equal(JSON.stringify(seen[1]).includes('NEW-ROUTE-BODY'),false);assert.equal((JSON.stringify(seen[2]).match(/NEW-ROUTE-BODY/g)||[]).length,1);});

test('PID birth mismatch recovers only with observable OS evidence; unavailable proof preserves the live-owner gate',async()=>{const f=await fixture();await seedInterrupted(f);const row=f.sessionStore.records.get(runtimeKey('execution','x'));row.value.owner={pid:process.pid,instanceId:'previous-birth',startIdentity:'not-this-process-start'};const next=nextSubmission(f,2,'safe after pid reuse'),restored=new BuiltinInteractionRuntime(f.options),observed=spawnSync('/bin/ps',['-p',String(process.pid),'-o','lstart='],{encoding:'utf8',timeout:1000}),hasEvidence=observed.status===0&&!!observed.stdout.trim(),receipt=await restored.submit(next);assert.equal(receipt.status,hasEvidence?'accepted':'rejected');if(hasEvidence){assert.equal((await finished({...f,adapter:restored,execution:next.payload.execution,submission:next})).status,'succeeded');assert.equal((await restored.getStatus(request({execution:f.execution}))).value.status,'unknown');}else{assert.equal(f.sessionStore.records.get(runtimeKey('session','c')).value.activeExecution,'x');assert.equal(row.value.status,'running');}});

test('graceful runtime shutdown records started unknown and preserves unstarted pending for automatic recovery',async()=>{let enter,calls=0;const started=new Promise(r=>enter=r);const f=await fixture({modelClient:{async complete({signal}){if(++calls===1){enter();return new Promise((_,reject)=>signal.addEventListener('abort',()=>reject(Error('interrupted')),{once:true}));}return response({text:'pending resumed'});}}});await f.adapter.submit(f.submission);await started;const next=nextSubmission(f,2,'PENDING-ON-SHUTDOWN');await f.adapter.submit(next);await f.adapter.shutdown();assert.equal(f.sessionStore.records.get(runtimeKey('execution','x')).value.status,'unknown');assert.equal(f.sessionStore.records.get(runtimeKey('execution','x2')).value.status,'queued');const restored=new BuiltinInteractionRuntime(f.options);assert.equal((await finished({...f,adapter:restored,execution:next.payload.execution,submission:next})).status,'succeeded');assert.equal(calls,2);assert.equal((await restored.getStatus(request({execution:f.execution}))).value.status,'unknown');});


test('trusted sent-message projection commits with input before model and survives adapter restart without a duplicate assistant notice',async()=>{
 let f,observed=0;const notice={role:'assistant',content:'Previously sent synthetic question',contextSource:{kind:'human_notice',id:'notice-one',occurredAt:1}};
 const project=async(messages,_context,projected)=>{if(projected.includes('notice-one')||messages.some(m=>m.contextSource?.id==='notice-one'))return messages;const index=messages.findIndex(m=>m.contextSource?.kind==='user_input');assert.ok(index>=0);return[...messages.slice(0,index),notice,...messages.slice(index)];};
 f=await fixture({prepareInputHistory:project,modelClient:{async complete(input){observed++;assert.equal(input.messages.filter(m=>m.contextSource?.id==='notice-one').length,observed===1?1:0);const session=[...f.sessionStore.records.values()].map(x=>x.value).find(x=>x.handle?.sessionId==='c');const persisted=f.options.journal.readMany({workspaceId:'w',entityId:'e',conversationId:'c'},session.messageRefs);assert.equal(persisted.filter(m=>m.contextSource?.id==='notice-one').length,observed===1?1:0,'notice must be durable, never replayed after retired history');return response();}}});
 assert.equal(observed,0);await f.adapter.submit(f.submission);assert.equal((await finished(f)).status,'succeeded');await f.adapter.shutdown();const record=[...f.sessionStore.records.entries()].find(([,x])=>x.value.handle?.sessionId==='c');assert.deepEqual(record[1].value.projectedNoticeIds,['notice-one']);const history=record[1].value.messageRefs.filter(ref=>f.options.journal.read({workspaceId:'w',entityId:'e',conversationId:'c'},ref).contextSource?.id!=='notice-one');f.sessionStore.records.set(record[0],{version:record[1].version+1,value:{...record[1].value,messageRefs:history}});const restarted=new BuiltinInteractionRuntime(f.options),target={...f.execution.target,turnId:'turn-two',epoch:2},execution={...f.execution,executionId:'x-two',invocationId:'i-two',target},submission={...f.submission,operationId:'op-two',authorizationContext:{...f.submission.authorizationContext,triggerId:'trigger-two',invocationId:'i-two',target},payload:{...f.submission.payload,execution,input:{...target,messageRefs:[ref('second reply')]},idempotencyKey:'second-turn'}};
 f.adapter=restarted;f.execution=execution;f.submission=submission;await restarted.submit(submission);assert.equal((await finished(f)).status,'succeeded');assert.equal(observed,2);await restarted.shutdown();
});
